import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {resolve,join} from 'node:path';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,lstatSync,chmodSync,readdirSync,rmSync,symlinkSync,existsSync} from 'node:fs';
const artifact=createRequire(import.meta.url)('./next-production-artifact.cjs');
const binding={sourceCommit:'a'.repeat(40),sourceTree:'b'.repeat(40),inputHashes:{lock:'c'.repeat(64)},compileEnv:{NODE_OPTIONS:'--max-old-space-size=2048'},nodeVersion:process.version};
function fixture(){const root=mkdtempSync(join(resolve('.'),'.next-prod-artifact-test-'));chmodSync(root,0o700);mkdirSync(join(root,'original/apps/web'),{recursive:true,mode:0o700});writeFileSync(join(root,'original/apps/web/server.js'),'server-original',{mode:0o600});return root;}
function cleanup(root:string){const open=(dir:string)=>{chmodSync(dir,0o700);for(const name of readdirSync(dir)){const p=join(dir,name),st=lstatSync(p);if(st.isDirectory()&&!st.isSymbolicLink())open(p);else if(!st.isSymbolicLink())chmodSync(p,0o600);}};open(root);rmSync(root,{recursive:true,force:true});}
test('whole-byte source/env bound artifact remains readonly and runtime has independent bytes',()=>{const root=fixture();try{writeFileSync(join(root,'original/apps/web/helper'),'executable-helper',{mode:0o700});artifact.seal(root,binding);assert.equal(lstatSync(join(root,'original/apps/web/helper')).mode&0o777,0o500);assert.equal(lstatSync(join(root,'original')).mode&0o777,0o500);assert.equal(lstatSync(join(root,'original/apps/web/server.js')).mode&0o777,0o400);artifact.verify(root,binding);const entry=artifact.runtimeCopy(root,binding);assert.equal(lstatSync(join(root,'runtime/apps/web/helper')).mode&0o777,0o700);writeFileSync(entry,'runtime cache/workspace mutation');assert.equal(readFileSync(join(root,'original/apps/web/server.js'),'utf8'),'server-original');artifact.verify(root,binding);assert.throws(()=>artifact.runtimeCopy(root,binding));assert.throws(()=>artifact.verify(root,{...binding,compileEnv:{NODE_OPTIONS:'--max-old-space-size=4096'}}));assert.throws(()=>artifact.verify(root,{...binding,sourceCommit:'d'.repeat(40)}));}finally{cleanup(root);}});
test('unknown files, changed bytes and linked summary cannot authorize launch',()=>{for(const change of ['bytes','addition','summary-link','manifest-byte']){const root=fixture();try{artifact.seal(root,binding);if(change==='bytes'){chmodSync(join(root,'original/apps/web/server.js'),0o600);writeFileSync(join(root,'original/apps/web/server.js'),'changed');}if(change==='addition'){chmodSync(join(root,'original'),0o700);writeFileSync(join(root,'original/new-file'),'unknown');}if(change==='summary-link'){const raw=readFileSync(join(root,'summary.json'));rmSync(join(root,'summary.json'));writeFileSync(join(root,'replacement'),raw);symlinkSync(join(root,'replacement'),join(root,'summary.json'));}if(change==='manifest-byte')writeFileSync(join(root,'files.json'),'{}');assert.throws(()=>artifact.verify(root,binding));}finally{cleanup(root);}}});
test('canonical closure rejects cycles, escape and bounds before copying overflowing bytes',()=>{const root=fixture();try{const source=join(root,'source');mkdirSync(source,{mode:0o700});writeFileSync(join(source,'large'),'12345');const output=join(root,'bounded');assert.throws(()=>artifact.canonicalCopy(source,output,{bytes:4}));assert.equal(existsSync(join(output,'large')),false);const cyclic=join(root,'cyclic');mkdirSync(cyclic,{mode:0o700});symlinkSync(cyclic,join(cyclic,'again'));assert.throws(()=>artifact.canonicalCopy(cyclic,join(root,'cycle-copy')));const escaping=join(root,'escaping');mkdirSync(escaping,{mode:0o700});symlinkSync('/etc/hosts',join(escaping,'external'));assert.throws(()=>artifact.canonicalCopy(escaping,join(root,'escape-copy')));const budget={files:0,bytes:0,dirs:0};artifact.canonicalCopy(source,join(root,'first'),{bytes:8},budget);assert.throws(()=>artifact.canonicalCopy(source,join(root,'second'),{bytes:8},budget));assert.equal(existsSync(join(root,'second/large')),false);}finally{cleanup(root);}});
test('summary schema rejects extra metadata and does not rely on BUILD_ID',()=>{const root=fixture();try{writeFileSync(join(root,'original/apps/web/BUILD_ID'),'same-id');artifact.seal(root,binding);const summary=JSON.parse(readFileSync(join(root,'summary.json'),'utf8'));writeFileSync(join(root,'summary.json'),JSON.stringify({...summary,secret:'must-not-export'}));assert.throws(()=>artifact.verify(root,binding));}finally{cleanup(root);}});
test('unknown empty directory and oversized summary fail closed',()=>{for(const change of ['directory','oversize']){const root=fixture();try{artifact.seal(root,binding);if(change==='directory'){chmodSync(join(root,'original'),0o700);mkdirSync(join(root,'original/unknown'),{mode:0o500});chmodSync(join(root,'original'),0o500);}else writeFileSync(join(root,'summary.json'),' '.repeat(16385));assert.throws(()=>artifact.verify(root,binding));}finally{cleanup(root);}}});
test('controlled build and serve do not inherit host secrets and reject conflicting flags',()=>{const bound={...binding,compileEnv:{...binding.compileEnv,NEXT_PUBLIC_API_URL:'http://127.0.0.1:3100',CHAT_READ_E2E_API_ORIGIN:'http://127.0.0.1:4100',WORKSPACEX_RELEASE_BUILD:'1'}};const env={PATH:'/bin',HOME:'/private/home',AWS_SECRET_ACCESS_KEY:'secret',DATABASE_URL:'secret',CN_SIX_WEB_MODE:'production-single',CN_SIX_WEB_ARTIFACT:'/private/artifact',CN_SIX_REPORT_PATH:'/private/report'};const compile=artifact.controlledBuildEnv(env,bound);assert.equal(compile.AWS_SECRET_ACCESS_KEY,undefined);assert.equal(compile.DATABASE_URL,undefined);assert.equal(compile.CN_SIX_WEB_ARTIFACT,undefined);const runtime=artifact.controlledRuntimeEnv({...env,APP_API_PORT:'4100'},bound);assert.equal(runtime.APP_API_PORT,'4100');assert.equal(runtime.DATABASE_URL,undefined);assert.equal(runtime.CN_SIX_WEB_ARTIFACT,env.CN_SIX_WEB_ARTIFACT);for(const bad of [{NEXT_PUBLIC_UNKNOWN:'x'},{FULLSTACK_E2E_SECRET:'x'},{CHAT_READ_E2E_API_ORIGIN:'http://evil'},{WSX_BOARD_TEST:'x'},{WORKSPACEX_RELEASE_BUILD:'0'},{NODE_OPTIONS:'--require secret'}])assert.throws(()=>artifact.controlledBuildEnv({...env,...bad},bound));assert.throws(()=>artifact.controlledRuntimeEnv({...env,APP_API_PORT:'4200'},bound));});
test('write-all preserves bytes under short writes and rejects zero progress',()=>{const fs=createRequire(import.meta.url)('node:fs');const root=fixture(),original=fs.writeSync;try{const file=join(root,'short'),fd=fs.openSync(file,'wx',0o600);fs.writeSync=(f:number,b:Buffer,o:number,n:number)=>original(f,b,o,Math.min(2,n));try{artifact.writeAll(fd,Buffer.from('complete-content'));}finally{fs.closeSync(fd);fs.writeSync=original;}assert.equal(readFileSync(file,'utf8'),'complete-content');fs.writeSync=()=>0;assert.throws(()=>artifact.writeAll(0,Buffer.from('x')));}finally{fs.writeSync=original;cleanup(root);}});
test('bounded reads reject append, named inode replacement, uid change and hardlinks',()=>{const fs=createRequire(import.meta.url)('node:fs');for(const change of ['append','swap','uid','hardlink']){const root=fixture(),file=join(root,'original/apps/web/server.js'),oldLstat=fs.lstatSync;try{if(change==='hardlink'){fs.linkSync(file,join(root,'second'));assert.throws(()=>artifact.hashFile(file));continue;}let first=true;if(change==='uid')fs.lstatSync=(p:string,...args:any[])=>{const st=oldLstat(p,...args);if(p===file)Object.defineProperty(st,'uid',{value:st.uid+1});return st;};assert.throws(()=>artifact.readBound(file,1024,()=>{if(!first)return;first=false;if(change==='append')fs.appendFileSync(file,'growth');if(change==='swap'){fs.renameSync(file,file+'.old');writeFileSync(file,'server-original',{mode:0o600});}}));}finally{fs.lstatSync=oldLstat;cleanup(root);}}});
test('directory snapshot rejects named inode replacement during enumeration',()=>{const fs=createRequire(import.meta.url)('node:fs'),root=fixture(),original=fs.readdirSync,dir=join(root,'original');try{let swapped=false;fs.readdirSync=(p:string,...args:any[])=>{const names=original(p,...args);if(p===dir&&!swapped){swapped=true;fs.renameSync(dir,dir+'.old');mkdirSync(dir,{mode:0o700});}return names;};assert.throws(()=>artifact.inventory(dir));}finally{fs.readdirSync=original;cleanup(root);}});
test('copy shared remaining and runtime entry size stop growth before writing overflow',()=>{const fs=createRequire(import.meta.url)('node:fs');for(const kind of ['canonical','runtime']){const root=fixture(),source=join(root,'original/apps/web/server.js'),oldOpen=fs.openSync,oldLstat=fs.lstatSync;try{if(kind==='runtime')artifact.seal(root,binding);let seen=0;if(kind==='canonical'){fs.lstatSync=(p:string,...args:any[])=>{const st=oldLstat(p,...args);if(p===source&&++seen===1)fs.appendFileSync(source,'growth');return st;};assert.throws(()=>artifact.canonicalCopy(source,join(root,'copy'),{bytes:15}));assert.equal(existsSync(join(root,'copy'))?lstatSync(join(root,'copy')).size:0,0);}else{fs.openSync=(p:string,...args:any[])=>{if(p===source&&++seen===3){chmodSync(source,0o600);fs.appendFileSync(source,'growth');}return oldOpen(p,...args);};assert.throws(()=>artifact.runtimeCopy(root,binding));const target=join(root,'runtime/apps/web/server.js');assert.equal(existsSync(target)?lstatSync(target).size:0,0);}}finally{fs.openSync=oldOpen;fs.lstatSync=oldLstat;cleanup(root);}}});
test('unaccounted top-level bytes cannot seal or verify artifact',()=>{for(const prepared of [false,true]){const root=fixture();try{if(prepared)artifact.seal(root,binding);writeFileSync(join(root,'unaccounted-private'),'extra bytes',{mode:0o600});assert.throws(()=>prepared?artifact.verify(root,binding):artifact.seal(root,binding));}finally{cleanup(root);}}});

test('installed Next defaults preserve registered production dist types without source rewrite',async()=>{const require=createRequire(import.meta.url),web=resolve('apps/web'),ts=require(require.resolve('typescript',{paths:[web]})),writer=require(require.resolve('next/dist/lib/typescript/writeConfigurationDefaults',{paths:[web]})).writeConfigurationDefaults;const root=mkdtempSync(join(web,'.next-prod-default-test-'));try{const config=JSON.parse(readFileSync(join(web,'tsconfig.json'),'utf8'));assert.ok(config.include.includes(artifact.DIST+'/types/**/*.ts'));if(config.extends)config.extends=resolve(web,config.extends);const file=join(root,'tsconfig.json');writeFileSync(file,JSON.stringify(config)+'\n');const before=readFileSync(file);await writer(ts,file,false,true,artifact.DIST,false);assert.deepEqual(readFileSync(file),before);}finally{rmSync(root,{recursive:true,force:true});}});
test('source closure accepts captured checkout owner plus builder but rejects unknown and private mixed owners',()=>{const fs=createRequire(import.meta.url)('node:fs'),root=fixture(),repo=resolve('.'),lstat=fs.lstatSync,fstat=fs.fstatSync;try{const source=join(root,'source');mkdirSync(source,{mode:0o700});const checkout=join(source,'checkout'),builder=join(source,'builder');writeFileSync(checkout,'checkout-owner');writeFileSync(builder,'builder-owner');const checkoutUid=process.getuid()+1000,unknownUid=checkoutUid+1;const uids=new Map<number,number>([[lstat(repo).ino,checkoutUid],[lstat(source).ino,checkoutUid],[lstat(checkout).ino,checkoutUid]]);const transform=(st:any)=>{if(uids.has(st.ino))Object.defineProperty(st,'uid',{value:uids.get(st.ino)});return st;};fs.lstatSync=(p:string,...args:any[])=>transform(lstat(p,...args));fs.fstatSync=(fd:number,...args:any[])=>transform(fstat(fd,...args));artifact.canonicalCopy(source,join(root,'mixed-copy'));assert.equal(readFileSync(join(root,'mixed-copy/checkout'),'utf8'),'checkout-owner');assert.equal(lstat(join(root,'mixed-copy/checkout')).uid,process.getuid());uids.set(lstat(checkout).ino,unknownUid);assert.throws(()=>artifact.canonicalCopy(source,join(root,'unknown-copy')));uids.set(lstat(join(root,'original/apps/web/server.js')).ino,checkoutUid);assert.throws(()=>artifact.seal(root,binding));}finally{fs.lstatSync=lstat;fs.fstatSync=fstat;cleanup(root);}});
